const root=document.getElementById('bulk-prices-root');
if(root){
const key='colafix-bulk-prices-v1',money=v=>'R$ '+Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;try{data=JSON.parse(localStorage.getItem(key))}catch{}if(!data||!Array.isArray(data.quotes)||!Array.isArray(data.contracts))data={quotes:[],contracts:[]};
let tab='prices',range=6;
const save=()=>localStorage.setItem(key,JSON.stringify(data));
const latest=s=>data.quotes.find(q=>q.supplier===s);
const rows=()=>[...data.quotes].sort((a,b)=>b.date.localeCompare(a.date));
const table=(heads,body)=>'<div class="bulk-scroll"><table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div>';
const chart=()=>{const days=[...new Set(rows().map(q=>q.date))].sort().slice(-range).reverse(),names=['Votorantim','Intercement'];if(!days.length)return '<p>Cadastre cotações para visualizar o gráfico.</p>';const vals=data.quotes.filter(q=>days.includes(q.date)).map(q=>Number(q.price)),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;return '<svg viewBox="0 0 600 170" width="100%" height="190" role="img" aria-label="Evolução dos preços">'+names.map((s,k)=>{const pts=days.map((d,i)=>{const q=data.quotes.find(x=>x.supplier===s&&x.date===d);return q?[30+i*540/Math.max(1,days.length-1),145-(Number(q.price)-min)/span*110]:null}).filter(Boolean);return '<polyline fill="none" stroke="'+(k?'#ef4444':'#1683f6')+'" stroke-width="3" points="'+pts.map(p=>p.join(',')).join(' ')+'"/>'+pts.map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="4" fill="'+(k?'#ef4444':'#1683f6')+'"/>').join('')}).join('')+'</svg><div>🔵 Votorantim &nbsp; 🔴 InterCement</div>'};
function draw(){const v=latest('Votorantim'),i=latest('Intercement');const q=(s,x)=>'<article class="bulk-panel"><h2 class="'+(s==='Intercement'?'bulk-red':'bulk-blue')+'">'+(s==='Votorantim'?'◢ Votorantim Cimentos':'◉ InterCement')+'</h2><small>Preço atual (R$/t)</small><h1>'+(x?money(x.price):'Não cadastrado')+'</h1><small>'+(x?'Atualizado em '+esc(x.date.split('-').reverse().join('/')):'Cadastre a primeira cotação')+'</small></article>';root.innerHTML='<div class="bulk-head"><h2>Cimento a Granel</h2><small>Preços, contratos vigentes e histórico de cotações.</small></div><div class="bulk-tabs"><button data-bulk-tab="prices" '+(tab==='prices'?'class="active"':'')+'>Preços</button><button data-bulk-tab="contracts" '+(tab==='contracts'?'class="active"':'')+'>Contratos Votorantim</button><button data-bulk-tab="history" '+(tab==='history'?'class="active"':'')+'>Histórico</button></div>'+
(tab==='prices'?'<div class="bulk-grid">'+q('Votorantim',v)+q('Intercement',i)+'<article class="bulk-panel"><h3>📊 Comparativo rápido (R$/t)</h3>'+table(['Fornecedor','Preço atual'],[['Votorantim',v],['InterCement',i]].map(([s,x])=>'<tr><td>'+s+'</td><td>'+(x?money(x.price):'—')+'</td></tr>').join('')+'<tr><th>Diferença</th><th>'+(v&&i?money(Math.abs(v.price-i.price)):'—')+'</th></tr>')+'</article></div><div class="bulk-grid bulk-grid-two"><article class="bulk-panel"><h3>📈 Evolução dos preços</h3>'+chart()+'</article><article class="bulk-panel"><h3>Últimas cotações</h3>'+table(['Data','Fornecedor','Preço'],rows().slice(0,8).map(x=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.supplier)+'</td><td>'+money(x.price)+'</td></tr>').join(''))+'</article></div><div class="bulk-panel"><h3>Nova cotação</h3><form id="bulk-quote-form" class="bulk-form"><select name="supplier"><option>Votorantim</option><option>Intercement</option></select><input name="date" type="date" required value="'+new Date().toISOString().slice(0,10)+'"><input name="price" type="number" min="0.01" step="0.01" placeholder="Preço por tonelada" required><button>Salvar cotação</button></form></div>':
tab==='contracts'?'<div class="bulk-panel"><h3>Contratos vigentes — Votorantim</h3>'+table(['Contrato','Produto','Início','Fim','Preço (R$/t)','Situação'],data.contracts.map(x=>'<tr><td>'+esc(x.number)+'</td><td>'+esc(x.product)+'</td><td>'+esc(x.start)+'</td><td>'+esc(x.end)+'</td><td>'+money(x.price)+'</td><td>'+(x.end>=new Date().toISOString().slice(0,10)?'Vigente':'Encerrado')+'</td></tr>').join(''))+'<h3>Novo contrato</h3><form id="bulk-contract-form" class="bulk-form"><input name="number" placeholder="Nº contrato" required><input name="product" placeholder="Produto" required><input name="start" type="date" required><input name="end" type="date" required><input name="price" type="number" step="0.01" min="0" placeholder="Preço R$/t" required><button>Salvar contrato</button></form></div>':
'<div class="bulk-panel"><h3>Histórico de preços</h3><div class="bulk-tabs">'+[3,6,12].map(n=>'<button data-range="'+n+'" '+(range===n?'class="active"':'')+'>'+n+'M</button>').join('')+'</div>'+chart()+table(['Data','Fornecedor','Preço (R$/t)'],rows().map(x=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.supplier)+'</td><td>'+money(x.price)+'</td></tr>').join(''))+'</div>');
root.querySelectorAll('[data-bulk-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.bulkTab;draw()});root.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{range=Number(b.dataset.range);draw()});
const qf=root.querySelector('#bulk-quote-form');if(qf)qf.onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(qf));data.quotes=data.quotes.filter(x=>!(x.date===o.date&&x.supplier===o.supplier));data.quotes.push({...o,price:Number(o.price)});save();draw()};
const cf=root.querySelector('#bulk-contract-form');if(cf)cf.onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(cf));data.contracts.push({...o,price:Number(o.price)});save();draw()};}
draw();}
